import {setupPwa} from './install.js';
import {applyTheme,themeOptions} from './theme.js';
import {nextOccurrence} from './dates.js';
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v10H3Z M9 20v-7h6v7',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',photo:'M3 3h18v18H3Z M3 16l5-5 4 4 3-3 6 6 M16 7h.01',music:'M9 18V5l12-2v13 M9 5l12-2 M9 18a3 3 0 1 1-3-3h3 M21 16a3 3 0 1 1-3-3h3',calendar:'M4 5h16v16H4Z M16 3v4 M8 3v4 M4 10h16 M8 14h2 M14 14h2',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z',plan:'M9 4h11v17H4V4h5 M9 3h6v4H9Z M8 12l2 2 5-5 M8 18h8',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',arrow:'M5 12h14 M14 7l5 5-5 5',plus:'M12 5v14 M5 12h14',lock:'M6 10h12v11H6Z M8 10V6a4 4 0 0 1 8 0v4',close:'m6 6 12 12 M18 6 6 18',check:'m4 12 5 5L20 6',edit:'m4 16 12-12 4 4L8 20H4Z',trash:'M3 6h18 M9 6V3h6v3 M6 6l1 15h10l1-15',back:'m14 5-7 7 7 7',play:'m8 4 12 8-12 8Z',cloud:'M7 18H6a5 5 0 1 1 1-10 6 6 0 0 1 11 0 5 5 0 0 1 0 10h-1 M12 12v9 m-3-6 3-3 3 3',note:'M4 3h16v18H4Z M8 8h8 M8 12h8 M8 16h5',sun:'M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10 M12 1v3 M12 20v3 M1 12h3 M20 12h3 M4 4l2 2 M18 18l2 2 M4 20l2-2 M18 6l2-2',pin:'M12 22s7-6.1 7-13a7 7 0 1 0-14 0c0 6.9 7 13 7 13Z M12 6a3 3 0 1 1 0 6 3 3 0 0 1 0-6Z'};
const lucide=(name,label='')=>`<i data-lucide="${name}" aria-hidden="true"></i>${label?`<span>${esc(label)}</span>`:''}`;
const refreshIcons=()=>window.lucide?.createIcons?.({attrs:{'stroke-width':1.8}});
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[name]||paths.spark}"/></svg>`;
const nav=[['inicio','home','Nuestro espacio'],['album','photo','Nuestro álbum'],['recuerdos','heart','La historia'],['musica','music','Nuestra música'],['calendario','calendar','Días especiales'],['planes','plan','Planes juntos'],['conectar','spark','Conectar'],['mapa','pin','Nuestro mapa']];
const bgAudio=new Audio('./regalo/musica.mp3');bgAudio.preload='auto';bgAudio.loop=true;
let musicUnlocked=false,currentTrack={id:'original',title:'Nuestra canción',src:'./regalo/musica.mp3'};
async function tryMusic(){if(!bgAudio.paused)return true;try{await bgAudio.play();musicUnlocked=true;return true;}catch{return false;}}
function unlockMusic(){if(musicUnlocked)return;tryMusic();}
function setTrack(src,title,id){if(!src)return;if(bgAudio.src!==new URL(src,location.href).href){bgAudio.src=src;bgAudio.load();}currentTrack={src,title,id};tryMusic();updateMiniPlayer();}
function updateMiniPlayer(){const el=document.querySelector('#global-player');if(!el)return;el.innerHTML=`<button class="icon-button" data-action="music-toggle" aria-label="${bgAudio.paused?'Reproducir':'Pausar'}">${icon(bgAudio.paused?'play':'close')}</button><div><small>SONANDO AHORA</small><b>${esc(currentTrack.title)}</b></div><a href="#musica" class="text-link">Música</a>`;}
let mapInstance=null,mapMarkers={},mapAccuracy={},mapPlaceMarkers={},mapTripLines={},locationWatch=null,locationPoll=null,locationUnsubscribe=null,lastLocationSent=0,lastTripSent=0,lastHistorySent=0,locationRows=[],mapPlaces=[],mapTripPoints=[],mapHistory=[],tripHistory=[],placeEvents=[],motionSamples=[],lastMotionPoint=null,placePresence={};
let state,view=location.hash.slice(1)||'inicio',filter='Todos',month=new Date().getMonth(),year=new Date().getFullYear(),photos=[],drivePhotos=[],drivePage='',photoSource='local',ideaIndex=0,pickerId=sessionStorage.getItem('pickerId')||'',search='',toastTimer;
const moods={feliz:['☀','Feliz'],tranquilo:['≈','En calma'],cansado:['☾','Sin energía'],sensible:['♡','Sensible'],abrazo:['∞','Necesito un abrazo']};
const items=kind=>state.items.filter(i=>i.kind===kind);
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),5000);}
async function api(url,options={}){
 const r=await fetch(url,{...options,headers:{...(options.body && !(options.body instanceof Blob)?{'Content-Type':'application/json'}:{}),...(state?.csrf?{'X-CSRF-Token':state.csrf}:{}),...options.headers}});
 const data=await r.json();if(!r.ok)throw Error(data.error||'No pudimos completar la acción.');return data;
}
async function refresh(render=true){state=await api('/api/state');if(render)draw();}
function dateLabel(date,options={}){if(!date)return'Sin fecha · un recuerdo para siempre';return new Intl.DateTimeFormat('es-CO',{day:'numeric',month:'long',...options}).format(new Date(date+'T12:00:00'));}
function nextDate(d){return nextOccurrence(d.date,d.annual,state.today);}
function upcoming(){return items('event').map(e=>({...e,next:nextDate(e.data)})).filter(e=>e.next>=state.today).sort((a,b)=>a.next.localeCompare(b.next));}
function days(date){return Math.round((Date.parse(date+'T12:00:00Z')-Date.parse(state.today+'T12:00:00Z'))/86400000);}
function heading(kicker,title,sub,action=''){return `<div class="page-heading"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1><p class="muted">${sub}</p></div>${action}</div>`;}
function btn(label,action,kind='primary',extra=''){return `<button class="btn ${kind}" data-action="${action}" ${extra}>${label}</button>`;}
function empty(symbol,title,copy,action=''){return `<div class="empty"><span class="empty-icon">${icon(symbol)}</span><h3>${title}</h3><p>${copy}</p>${action}</div>`;}
function formError(message){const el=modal.querySelector('.form-error');if(el){el.textContent=message;el.focus();}else toast(message);}
function show(content,wide=false){modal.className=wide?'wide':'';modal.innerHTML=`<button class="close icon-button" data-action="close" aria-label="Cerrar">${icon('close')}</button>${content}`;modal.showModal();}
function close(){modal.querySelectorAll('iframe').forEach(f=>f.remove());modal.close();}
function draw(){
 if(mapInstance){mapInstance.remove();mapInstance=null;mapMarkers={};mapAccuracy={};mapPlaceMarkers={};mapTripLines={};}
 document.documentElement.classList.remove('home-fullscreen');
 const names=state.settings.data.names;
 app.innerHTML=`<aside class="sidebar"><a class="brand" href="#inicio"><img src="/icon.svg" alt="" width="39" height="39"><span>Nuestra<br><strong>galaxia</strong></span></a><div class="couple-card"><div class="avatars"><span>${esc(names[0][0])}</span><span>${esc(names[1][0])}</span></div><b>${esc(names.join(' & '))}</b><small>Un pequeño universo, solo nuestro</small></div><p class="nav-label">LO QUE SOMOS</p><nav aria-label="Navegación principal">${nav.map(([id,i,label])=>`<a href="#${id}" ${view===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${view===id?'<i></i>':''}</a>`).join('')}</nav><a class="gift-link" href="/regalo/">${icon('sun')}<span>Donde todo floreció<small>Volver a tu regalo original</small></span>${icon('arrow')}</a><div class="sidebar-bottom"><a href="#ajustes" ${view==='ajustes'?'aria-current="page"':''}>${icon('settings')} Nuestro espacio</a><span>${icon('lock')} Privado, como lo nuestro</span></div></aside>
 <div class="workspace"><div id="global-player" class="global-player"></div><header class="topbar"><div class="breadcrumb">Nuestro universo <span>/</span> ${esc(nav.find(n=>n[0]===view)?.[2]||'Ajustes')}</div><div class="topbar-right">${state.demo?`<label class="demo-person">Vista local <select id="demo-person" aria-label="Probar como">${names.map((n,i)=>`<option value="${i}" ${String(i)===state.person?'selected':''}>${esc(n)}</option>`).join('')}</select></label>`:`<span class="session-name">Hola, ${esc(names[Number(state.person)])}</span>`}<button class="avatar-button" data-action="settings" aria-label="Abrir ajustes">${esc(names[Number(state.person)][0])}</button></div></header><main id="main" tabindex="-1">${renderView()}</main><footer class="footer">Hecho para nosotros. Para lo cotidiano y lo extraordinario. ${icon('heart')}</footer></div>`;
 const more=document.createElement('button');more.className='mobile-more';more.dataset.action='more';more.innerHTML=icon('plus')+'<span>Más</span>';document.querySelector('nav').append(more);
 if(view==='album')loadPhotos();updateMiniPlayer();queueMicrotask(refreshIcons);if(view==='mapa')queueMicrotask(initMap);
}
function renderView(){switch(view){case'album':return album();case'recuerdos':return memories();case'musica':return music();case'calendario':return calendar();case'planes':return plans();case'conectar':return connect();case'mapa':return mapView();case'ajustes':return settings();default:return dashboard();}}
function dashboard(){const names=state.settings.data.names,start=state.settings.data.startDate,next=upcoming()[0],mine=state.daily.find(d=>d.person===state.person);return `
 ${heading('NUESTRO RINCÓN FAVORITO',`Qué bonito coincidir, ${esc(names[Number(state.person)])}.`,'Un lugar para guardar lo que vivimos y soñar lo que viene.',`<span class="today">${icon('calendar')}${dateLabel(state.today,{weekday:'long'})}</span>`)}
 <section class="hero"><div class="hero-copy"><span class="hero-tag">DOS PERSONAS. UN MISMO UNIVERSO.</span><h2>Lo mejor de la vida<br>es vivirla <em>contigo.</em></h2><p>Los días grandes, las canciones de siempre<br>y esas pequeñas cosas que solo entendemos nosotros.</p><div class="hero-actions"><a class="btn cream" href="#recuerdos">Nuestra historia ${icon('arrow')}</a><a class="hero-secondary" href="#planes">Soñemos el próximo plan</a></div><div class="hero-signature">${esc(names.join(' + '))}<span>siempre hay algo bonito por vivir</span></div></div><div class="hero-art"><img src="/garden.svg" alt="Ilustración de girasoles bajo un sol dorado"><span class="art-note">donde estás tú, florece todo.</span></div></section>
 <div class="stats"><a href="#ajustes" class="stat"><span class="stat-icon">${icon('heart')}</span><div><strong>${start?Math.max(0,-days(start)).toLocaleString('es-CO'):'Nuestra fecha'}</strong><span>${start?'días eligiéndonos':'¿Cuándo comenzó todo?'}</span></div>${icon('arrow')}</a><a href="#recuerdos" class="stat"><span class="stat-icon peach">${icon('photo')}</span><div><strong>${items('memory').length}</strong><span>recuerdos que son hogar</span></div>${icon('arrow')}</a><a href="#planes" class="stat"><span class="stat-icon lilac">${icon('spark')}</span><div><strong>${items('plan').filter(i=>!i.data.done).length}</strong><span>planes por vivir juntos</span></div>${icon('arrow')}</a></div>
 <div class="dashboard-grid"><section class="card daily-card"><div class="section-title"><div><span class="eyebrow">UN MINUTO PARA NOSOTROS</span><h2>¿Cómo está tu corazón hoy?</h2></div>${icon('heart')}</div><p class="muted">A veces, conectar empieza con una pequeña pregunta.</p><div class="moods">${Object.entries(moods).map(([key,[symbol,label]])=>`<button data-action="mood" data-value="${key}" class="mood ${mine?.mood===key?'selected':''}" aria-pressed="${mine?.mood===key}"><span>${symbol}</span>${label}</button>`).join('')}</div><div class="daily-status">${state.daily.length?state.daily.filter(d=>d.mood).map(d=>`<span><b>${esc(names[Number(d.person)])}</b> · ${esc(moods[d.mood]?.[1])}</span>`).join(''):'Este es un espacio para escucharse, sin respuestas correctas.'}</div></section>
 <section class="card upcoming-card"><div class="section-title"><h2>Lo que viene</h2><a href="#calendario" aria-label="Ver calendario">${icon('arrow')}</a></div>${next?`<div class="date-tile"><strong>${Number(next.next.slice(8))}</strong><span>${new Intl.DateTimeFormat('es',{month:'short'}).format(new Date(next.next+'T12:00:00'))}</span></div><h3>${esc(next.data.title)}</h3><p class="muted">${days(next.next)===0?'¡Es hoy!':`Faltan ${days(next.next)} días`} · ${next.data.annual?'Una fecha para celebrar cada año':'Un momento para ustedes'}</p>`:`<div class="upcoming-empty">${icon('calendar')}<p>Los mejores días merecen<br>un lugar especial.</p></div>`}${btn('Guardar una fecha '+icon('plus'),'new-event','secondary')}</section></div>
 <div class="section-title spaced"><div><span class="eyebrow">ASÍ EMPEZÓ NUESTRA GALAXIA</span><h2>Pequeños momentos, grandes recuerdos</h2></div><a class="text-link" href="#recuerdos">Ver la historia ${icon('arrow')}</a></div>
 <div class="memory-grid">${items('memory').slice(-3).map((m,i)=>memoryCard(m,i)).join('')}</div>
 <section class="question-banner"><div class="question-symbol">“</div><div><span class="eyebrow">LA PREGUNTA DE HOY</span><h2>${esc(state.question)}</h2><p>Respondan por separado. Descubran sus respuestas cuando ambos estén listos.</p></div><a class="btn secondary" href="#conectar">Un ratito para dos ${icon('arrow')}</a></section>`;}
function memoryCard(m,i){return `<button class="memory-card" data-action="detail" data-id="${m.id}"><div class="memory-art art-${i%4}"><span class="memory-doodle">${icon(['heart','sun','spark','photo'][i%4])}</span><span class="memory-category">${esc(m.data.category||'Un momento nuestro')}</span></div><div class="memory-copy"><small>${dateLabel(m.data.date)}</small><h3>${esc(m.data.title)}</h3><p>${esc(m.data.body)}</p><span class="text-link">Volver a ese momento ${icon('arrow')}</span></div></button>`;}
function memories(){const all=items('memory').filter(m=>(m.data.title+' '+m.data.body).toLowerCase().includes(search.toLowerCase()));return `${heading('LAS COSAS QUE NOS QUEDAN','Nuestra historia, a nuestra manera.','Un archivo de instantes que siempre vale la pena volver a vivir.',btn(icon('plus')+' Guardar recuerdo','new-memory'))}<div class="toolbar"><label class="search-box">Buscar en nuestra historia<input id="memory-search" value="${esc(search)}" placeholder="Un lugar, una palabra, un momento…"></label><span class="muted">${all.length} recuerdos</span></div><div class="memory-grid">${all.map(memoryCard).join('')}</div>${!all.length?empty('heart','Todavía no hay un recuerdo aquí.','Prueba otra palabra o guarda ese momento que no quieres olvidar.'):''}`;}
function album(){return `${heading('LA VIDA, EN FOTOGRAFÍAS','Nuestro álbum.','Los lugares cambian. Lo bonito es haber estado juntos.',btn(icon('plus')+' Añadir fotos','upload'))}<div class="album-banner"><div class="album-art">${icon('photo')}<span>nosotros,<br><em>una y otra vez.</em></span></div><div><span class="eyebrow">UN ÁLBUM CON MUCHAS HISTORIAS</span><h2>Todos nuestros «¿te acuerdas?»</h2><p class="muted">Trae las fotos que quieran conservar en este espacio. Solo ustedes dos podrán verlas aquí.</p><div class="button-row">${state.settings.data.albumUrl?`<a class="btn secondary" target="_blank" rel="noopener noreferrer" href="${esc(state.settings.data.albumUrl)}">Abrir nuestro Google Fotos ${icon('arrow')}</a>`:btn('Añadir enlace del álbum','settings','secondary')}${btn('Elegir de Google Fotos','picker','text-button')}</div></div></div><div class="toolbar"><div class="tabs" aria-label="Origen de las fotos"><button data-action="photo-source" data-value="local" class="${photoSource==='local'?'active':''}">Nuestro álbum</button><button data-action="photo-source" data-value="drive" class="${photoSource==='drive'?'active':''}">Carpeta de Drive</button></div><span class="muted" id="photo-count"></span></div>${pickerId?`<div class="notice">¿Ya terminaste de elegir en Google Fotos? ${btn('Importar selección','picker-import','secondary')}</div>`:''}<div id="photo-grid" class="photo-grid"><p class="muted">Abriendo el álbum…</p></div><input id="photo-upload" type="file" accept="image/jpeg,image/png,image/webp" multiple hidden>`;}
async function loadPhotos(){try{if(photoSource==='drive'){if(!state.connections.drive){document.querySelector('#photo-grid').innerHTML=empty('cloud','Su carpeta, en un solo lugar.','Conecta Google Drive y elige una carpeta compartida en Ajustes.',btn('Configurar Drive','settings'));return;}const data=await api('/api/drive/photos');drivePhotos=data.files||[];drivePage=data.nextPageToken||'';}else photos=(await api('/api/photos')).photos;if(view!=='album')return;renderPhotos();}catch(e){if(view==='album')document.querySelector('#photo-grid').innerHTML=empty('photo','No pudimos abrir las fotos.',esc(e.message),btn('Volver a intentar','reload-photos','secondary'));}}
function renderPhotos(){const data=photoSource==='drive'?drivePhotos:photos;document.querySelector('#photo-count').textContent=`${data.length} fotos`;document.querySelector('#photo-grid').innerHTML=data.length?data.map(p=>`<button class="photo-tile" data-action="photo" data-id="${esc(p.id)}"><img loading="lazy" src="${photoSource==='drive'?'/api/drive/image/':'/media/'}${encodeURIComponent(p.id)}" alt="${esc(p.name)}"><span>${esc(p.name)}</span></button>`).join('')+(drivePage&&photoSource==='drive'?btn('Ver más fotos','drive-more','secondary'):''):empty('photo','Aquí empieza su álbum.','Sube fotos del celular o elígelas desde Google Fotos. Nada se añade sin que ustedes lo escojan.',btn('Añadir nuestras primeras fotos','upload'));}
function songSource(s){return s.data.audioUrl||'';}
function music(){return `${heading('LA BANDA SONORA DE LO NUESTRO','Hay canciones que suenan a ti.','La música puede acompañarlos por toda la galaxia.',btn(icon('plus')+' Añadir canción','new-song'))}<section class="music-feature"><div class="vinyl"><div>✿</div></div><div><span class="eyebrow">SONANDO EN NUESTRA GALAXIA</span><h2>${esc(currentTrack.title)}</h2><p>La música continúa aunque cambies de sección.</p><div class="button-row">${btn(bgAudio.paused?icon('play')+' Reproducir':'Pausar','music-toggle','secondary')}</div></div><span class="music-feature-note">para escucharnos<br><em>un poquito más.</em></span></section><div class="section-title spaced"><h2>Nuestra selección</h2><span class="muted">MP3 · Spotify · YouTube</span></div><div class="song-grid">${items('song').map(s=>`<article class="card song-card"><div class="song-cover">${icon('music')}</div><span class="eyebrow">${esc(s.data.provider||'Nuestra música')}</span><h3>${esc(s.data.title)}</h3><p>${esc(s.data.body||'Una canción para compartir.')}</p><div class="button-row">${btn(icon('play')+' Reproducir','play-song','secondary',`data-id="${s.id}"`)}${btn(icon('edit'),'edit','icon-button',`data-id="${s.id}" aria-label="Editar canción"`)}</div></article>`).join('')}</div>${!items('song').length?empty('music','¿Cuál será nuestra primera canción?','Puedes pegar un enlace o subir directamente un MP3.',btn('Dedicar una canción','new-song','secondary')):''}<input id="song-upload" type="file" accept="audio/mpeg,.mp3" hidden><p class="fine-print">Spotify y YouTube dependen de las reglas de reproducción de cada servicio. Para reproducción directa y continua, usa un MP3.</p>`;}
function calendar(){const first=new Date(year,month,1),offset=(first.getDay()+6)%7,total=new Date(year,month+1,0).getDate();const events=items('event');const title=new Intl.DateTimeFormat('es',{month:'long',year:'numeric'}).format(first);let cells='';for(let i=0;i<offset;i++)cells+='<div class="calendar-blank"></div>';for(let d=1;d<=total;d++){const date=`${year}-${String(month+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;const on=events.filter(e=>e.data.annual?e.data.date.slice(5)===date.slice(5)&&e.data.date<=date:e.data.date===date);cells+=`<button class="day ${date===state.today?'is-today':''}" data-action="day" data-date="${date}" aria-label="${dateLabel(date,{year:'numeric'})}, ${on.length} eventos"><span>${d}</span>${on.slice(0,2).map(e=>`<small>${esc(e.data.title)}</small>`).join('')}${on.length>2?`<small>+${on.length-2} más</small>`:''}</button>`;}
 return `${heading('UN LUGAR PARA LOS DÍAS QUE IMPORTAN','Que no se nos olvide celebrar.','Cumpleaños, aniversarios, citas y cualquier excusa para estar juntos.',btn(icon('plus')+' Añadir fecha','new-event'))}<div class="calendar-layout"><section class="card calendar-card"><div class="calendar-controls"><h2>${title}</h2><div>${btn(icon('back'),'prev-month','icon-button','aria-label="Mes anterior"')}${btn('Hoy','today','text-button')}${btn(icon('arrow'),'next-month','icon-button','aria-label="Mes siguiente"')}</div></div><div class="calendar-grid">${['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].map(d=>`<span class="weekday">${d}</span>`).join('')}${cells}</div></section><aside class="card agenda"><span class="eyebrow">PARA IR CONTANDO LOS DÍAS</span><h2>Próximos momentos</h2>${upcoming().slice(0,6).map(e=>`<button class="agenda-item" data-action="detail" data-id="${e.id}"><span>${Number(e.next.slice(8))}<small>${new Intl.DateTimeFormat('es',{month:'short'}).format(new Date(e.next+'T12:00:00'))}</small></span><div><b>${esc(e.data.title)}</b><small>${days(e.next)===0?'Hoy':`En ${days(e.next)} días`}${e.data.annual?' · Cada año':''}</small></div></button>`).join('')||'<p class="muted">Todavía no hay fechas. Empiecen por la que más les haga sonreír.</p>'}<a class="btn secondary" href="/api/calendar.ics">Exportar calendario ${icon('calendar')}</a><p class="fine-print">Importa el archivo en Google Calendar, Apple Calendar u Outlook.</p></aside></div>`;}
function plans(){const list=items('plan').filter(i=>filter==='Todos'||(filter==='Por vivir'?!i.data.done:i.data.done));return `${heading('LO BONITO TAMBIÉN SE PLANTEA','Nos quedan tantos planes.','Una lista compartida para los «algún día» y los «¿y si hoy?».',btn(icon('plus')+' Proponer un plan','new-plan'))}<div class="plan-hero"><div><span class="eyebrow">UNA IDEA PARA SALIR DE LA RUTINA</span><h2>${esc(state.ideas[ideaIndex].title)}</h2><p>${esc(state.ideas[ideaIndex].text)}</p><div class="button-row">${btn('Lo queremos hacer '+icon('plus'),'save-idea','primary')}${btn('Sorpréndenos con otra','shuffle-idea','text-button')}</div></div><div class="plan-illustration" aria-hidden="true">${icon('spark')}<span>¿y si<br><em>nos escapamos?</em></span></div></div><div class="toolbar"><div class="tabs">${['Todos','Por vivir','Vividos'].map(f=>`<button data-action="filter" data-value="${f}" class="${filter===f?'active':''}">${f}</button>`).join('')}</div><span class="muted">${items('plan').filter(i=>i.data.done).length} planes hechos realidad</span></div><div class="plan-grid">${list.map(p=>`<article class="card plan-card ${p.data.done?'done':''}"><div class="section-title"><span class="pill">${esc(p.data.category||'Juntos')}</span>${btn(icon('edit'),'edit','icon-button',`data-id="${p.id}" aria-label="Editar plan"`)}</div><h3>${esc(p.data.title)}</h3><p class="muted">${esc(p.data.body)}</p><small>${p.data.date?dateLabel(p.data.date):'Sin prisa, pero con ganas'}</small><button class="complete-plan" data-action="complete" data-id="${p.id}" aria-pressed="${p.data.done}">${icon(p.data.done?'check':'plus')}${p.data.done?'Un recuerdo más':'Marcar como vivido'}</button></article>`).join('')}</div>${!list.length?empty('plan','Los próximos recuerdos empiezan aquí.','Agreguen una idea, pónganle fecha si quieren y háganla realidad.'):''}`;}
function connect(){const names=state.settings.data.names,mine=state.daily.find(d=>d.person===state.person);return `${heading('CUIDAR LO NUESTRO, UN POQUITO CADA DÍA','Un ratito para dos.','Sin puntuaciones ni rachas que cumplir. Solo una invitación a escucharse.')}<section class="connection-question"><span class="pill">${icon('spark')} La pregunta de hoy</span><h2>${esc(state.question)}</h2><p>Primero respondan a su manera. Las dos respuestas se revelan cuando ambos hayan escrito.</p><form id="answer-form"><label for="answer">Tu respuesta, ${esc(names[Number(state.person)])}</label><textarea id="answer" name="answer" maxlength="3000" required placeholder="Tómate tu tiempo…">${esc(mine?.answer||'')}</textarea><button class="btn primary" type="submit">${mine?.answered?'Actualizar mi respuesta':'Guardar mi respuesta'} ${icon('heart')}</button><p class="inline-error" role="alert"></p></form><div class="answer-grid">${names.map((n,i)=>{const d=state.daily.find(d=>d.person===String(i));return `<article><span class="answer-avatar">${esc(n[0])}</span><b>${esc(n)}</b><p>${d?.answer?esc(d.answer):d?.answered?'Su respuesta está guardada. Se abrirá cuando ambos respondan.':'Todavía está pensando su respuesta.'}</p></article>`;}).join('')}</div></section><div class="section-title spaced"><div><span class="eyebrow">EL AMOR TAMBIÉN ESTÁ EN LOS DETALLES</span><h2>Pequeñas formas de estar cerca</h2></div></div><div class="ritual-grid">${state.ideas.filter(i=>i.category==='Conectar').map((i)=>`<article class="card ritual-card">${icon('heart')}<span class="pill">${i.minutes} min · Para dos</span><h3>${esc(i.title)}</h3><p class="muted">${esc(i.text)}</p>${btn('Guardar como plan','ritual','text-button',`data-index="${state.ideas.indexOf(i)}"`)}</article>`).join('')}</div><div class="section-title spaced"><h2>Te dejo una notita</h2>${btn(icon('plus')+' Escribir algo bonito','new-note','secondary')}</div><div class="note-grid">${items('note').map(n=>`<button class="note-card" data-action="detail" data-id="${n.id}"><span>${icon('note')}</span><h3>${esc(n.data.title)}</h3><p>${esc(n.data.body)}</p><small>De ${esc(names[Number(n.author)]||names[0])}, con cariño</small></button>`).join('')||'<p class="muted">Un «gracias», un «te extraño», un «qué suerte tenerte». Empieza cuando quieras.</p>'}</div>`;}
function relativeLocationTime(value){if(!value)return'Sin ubicación';const seconds=Math.max(0,Math.round((Date.now()-Date.parse(value))/1000));if(seconds<15)return'Ahora';if(seconds<60)return'Hace '+seconds+' s';const minutes=Math.round(seconds/60);if(minutes<60)return'Hace '+minutes+' min';const hours=Math.round(minutes/60);return hours<24?'Hace '+hours+' h':'Hace más de un día';}
function locationStatus(row){if(!row?.sharing)return'No está compartiendo';const age=Date.now()-Date.parse(row.updated_at||0);return age<30000?'En vivo':age<300000?'Ubicación reciente':'Sin conexión · última ubicación';}
function distanceKm(a,b){if(!a||!b)return null;const R=6371,dLat=(Number(b.latitude)-Number(a.latitude))*Math.PI/180,dLon=(Number(b.longitude)-Number(a.longitude))*Math.PI/180,x=Math.sin(dLat/2)**2+Math.cos(Number(a.latitude)*Math.PI/180)*Math.cos(Number(b.latitude)*Math.PI/180)*Math.sin(dLon/2)**2;return 2*R*Math.asin(Math.sqrt(x));}
function mapView(){const names=state.settings.data.names,live=locationRows.filter(r=>r.sharing&&Number.isFinite(Number(r.latitude))),d=live.length===2?distanceKm(live[0],live[1]):null;return `
 ${heading('NUESTRO MAPA','Siempre cerquita.','Un mapa privado para cuidarse, encontrarse y guardar los lugares que forman su historia.')}
 <section class="map-v2-summary map-v2-summary-slim"><article class="card map-distance"><span class="eyebrow">DISTANCIA ENTRE NOSOTROS</span><h2 id="map-distance-value">${d==null?'Cuando ambos compartan ubicación aparecerá aquí':d<.08?'Juntitos ♡':d<1?Math.round(d*1000)+' m':d.toFixed(1)+' km'}</h2><p>Solo se calcula con las ubicaciones que ustedes deciden compartir.</p></article></section>
 <section class="location-layout map-focus-layout"><div class="location-map-card map-stage"><div id="couple-map" class="couple-map" role="region" aria-label="Mapa compartido"><div class="map-loading">Cargando nuestro mapa…</div></div><div class="map-floating-controls"><div class="map-floating-stack"><div class="map-status-fab-wrap"><button class="map-fab map-fab-status" data-action="status-menu" aria-label="Abrir estados rápidos" aria-expanded="false">${lucide('message-circle-heart')}</button><div id="map-status-menu" class="map-fab-menu map-status-menu" hidden><button data-action="location-status" data-value="Voy saliendo">${lucide('door-open','Voy saliendo')}</button><button data-action="location-status" data-value="Voy para casa">${lucide('house','Voy para casa')}</button><button data-action="location-status" data-value="Llegué">${lucide('badge-check','Llegué')}</button><button data-action="location-status" data-value="Estoy bien">${lucide('heart-pulse','Estoy bien')}</button><button data-action="location-status" data-value="Espérame">${lucide('clock-3','Espérame')}</button></div></div><button class="map-fab map-fab-main" data-action="map-menu" aria-label="Abrir acciones del mapa" aria-expanded="false">${lucide('plus')}</button></div><div id="map-fab-menu" class="map-fab-menu" hidden><button data-action="trip-toggle">${lucide('route','Acompáñame')}</button><button data-action="arrived">${lucide('badge-check','Ya llegué')}</button><button data-action="lost-mode">${lucide('navigation','Ayúdame a llegar')}</button><button data-action="place-new">${lucide('map-pin-plus','Guardar lugar')}</button><button data-action="place-home">${lucide('house','Casa aquí')}</button><button data-action="place-work">${lucide('briefcase-business','Trabajo aquí')}</button></div></div><div id="location-controls" class="map-share-control"></div><small class="map-note">Mapa © OpenStreetMap contributors · La precisión depende del GPS. Al mostrar el mapa, el área visible se solicita a OpenStreetMap.</small></div><aside class="location-panel compact-location-panel"><div id="location-people" class="location-people"></div><p class="fine-print">Compartir siempre es visible y se puede detener. Acompáñame elimina el recorrido al terminar.</p></aside></section>
 <section class="map-v2-grid"><article class="card"><span class="eyebrow">CASA Y TRABAJO</span><h2>Nuestros puntos seguros</h2><p>Guarda tu ubicación actual como Casa o Trabajo. Si permaneces cerca, Nuestra Galaxia podrá reconocer tu llegada.</p><div class="button-row">${btn('Guardar Casa aquí','place-home','secondary')}${btn('Guardar Trabajo aquí','place-work','secondary')}</div></article><article class="card"><span class="eyebrow">NUESTROS LUGARES</span><h2>Recuerdos y próximas aventuras</h2><div id="map-places-list">${mapPlaces.length?mapPlaces.map(p=>`<button class="map-place-row" data-action="place-focus" data-id="${p.id}"><b>${esc(p.name)}</b><small>${p.kind==='adventure'?'Próxima aventura':p.kind==='memory'?'Recuerdo':p.kind==='home'?'Casa':'Trabajo'}</small></button>`).join(''):'<p class="muted">Todavía no han guardado lugares.</p>'}</div></article><article class="card map-insights-card"><span class="eyebrow">MOVILIDAD</span><h2>Lo que hemos recorrido</h2><div id="map-insights">${mobilityInsights()}</div><button class="btn secondary" data-action="mobility-history">Ver recorridos</button></article><article class="card"><span class="eyebrow">PRIVACIDAD</span><h2>Tus datos, bajo tu control</h2><p id="map-data-summary">${privacySummary()}</p><div class="button-row"><button class="btn secondary" data-action="mobility-export">Exportar mis datos</button><button class="btn danger" data-action="mobility-clear">Borrar mi historial</button></div></article></section>`;}
async function loadLocations(fit=false){if(view!=='mapa')return;[locationRows,mapPlaces,mapTripPoints,mapHistory,tripHistory,placeEvents]=await Promise.all([api('/api/locations'),api('/api/map/places'),api('/api/map/trip'),api('/api/map/history'),api('/api/map/trip/history'),api('/api/map/place/events')]);renderLocations(fit);}
function mobilityInsights(){const names=state?.settings?.data?.names||['Persona 1','Persona 2'];if(!mapHistory.length&&!tripHistory.length)return'<p class="muted">Todavía estamos reuniendo datos de movimiento.</p>';return names.map((name,i)=>{const points=mapHistory.filter(x=>String(x.person)===String(i)),trips=tripHistory.filter(x=>String(x.person)===String(i)),km=trips.reduce((n,t)=>n+Number(t.distance_m||0),0)/1000,speeds=points.map(x=>Number(x.speed)).filter(Number.isFinite),avg=speeds.length?speeds.reduce((a,b)=>a+b,0)/speeds.length*3.6:0;return `<div class="mobility-stat"><b>${esc(name)}</b><span>${km.toFixed(1)} km · ${trips.length} recorridos</span><small>Velocidad media registrada ${avg.toFixed(1)} km/h</small></div>`;}).join('');}
function privacySummary(){const mine=String(state?.person),points=mapHistory.filter(x=>String(x.person)===mine).length,trips=tripHistory.filter(x=>String(x.person)===mine).length;return `${points} muestras recientes y ${trips} recorridos guardados. Solo se captura mientras compartes ubicación.`;}
function formatDuration(s){s=Number(s)||0;const h=Math.floor(s/3600),m=Math.round((s%3600)/60);return h?h+' h '+m+' min':m+' min';}
async function detectSmartPlace(latitude,longitude){const own=mapPlaces.filter(p=>String(p.owner)===String(state.person)&&['home','work'].includes(p.kind)),now=Date.now();for(const p of own){const meters=(distanceKm({latitude,longitude},p)||0)*1000,inside=meters<=Math.max(80,Number(latitude&&0)+80),key=String(p.id),s=placePresence[key]||{inside:false,since:0,arrived:false};if(inside){if(!s.inside){s.inside=true;s.since=now;}if(!s.arrived&&now-s.since>=45000){s.arrived=true;await api('/api/map/place/event',{method:'POST',body:JSON.stringify({place_id:p.id,event:'arrived'})});await api('/api/location',{method:'PUT',body:JSON.stringify({sharing:true,latitude,longitude,status:'Llegué a '+p.name})});toast('Llegaste a '+p.name+'.');}}else if(s.inside){if(s.arrived)await api('/api/map/place/event',{method:'POST',body:JSON.stringify({place_id:p.id,event:'left'})});s.inside=false;s.since=0;s.arrived=false;}placePresence[key]=s;}}
function renderMapMeta(){const live=locationRows.filter(r=>r.sharing&&Number.isFinite(Number(r.latitude))),d=live.length===2?distanceKm(live[0],live[1]):null,distance=document.querySelector('#map-distance-value'),places=document.querySelector('#map-places-list'),mine=locationRows.find(r=>String(r.person)===String(state.person));if(distance)distance.textContent=d==null?'Cuando ambos compartan ubicación aparecerá aquí':d<.08?'Juntitos':d<1?Math.round(d*1000)+' m':d.toFixed(1)+' km';if(places)places.innerHTML=mapPlaces.length?mapPlaces.map(p=>`<button class="map-place-row" data-action="place-focus" data-id="${p.id}"><b>${esc(p.name)}</b><small>${p.kind==='adventure'?'Próxima aventura':p.kind==='memory'?'Recuerdo':p.kind==='home'?'Casa':'Trabajo'}</small></button>`).join(''):'<p class="muted">Todavía no han guardado lugares.</p>';const trip=document.querySelector('[data-action="trip-toggle"]');if(trip)trip.innerHTML=lucide('route',mine?.trip_active?'Terminar Acompáñame':'Acompáñame');refreshIcons();}
function speedKmh(row){const n=Number(row?.speed);return Number.isFinite(n)&&n>=0?n*3.6:null;}
function motionLabel(row){if(!row?.sharing)return'';const kmh=speedKmh(row);if(row.motion==='walking')return'Caminando';if(row.motion==='vehicle')return row.transport_preference==='motorcycle'?'En moto · probable':row.transport_preference==='transit'?'En transporte público · probable':'En vehículo';if(row.motion==='still')return'Quieto';return kmh!=null&&kmh>=10?'En movimiento':'Calculando movimiento';}
function motionIcon(row){if(row?.motion==='walking')return'person-standing';if(row?.motion==='vehicle')return row.transport_preference==='motorcycle'?'bike':row.transport_preference==='transit'?'bus-front':'car-front';if(row?.motion==='still')return'map-pin';return'navigation';}
function motionMarkerHtml(row,name){const kmh=speedKmh(row),heading=Number(row?.heading),moving=row?.motion==='walking'||row?.motion==='vehicle',angle=moving&&Number.isFinite(heading)?heading:0;return `<div class="motion-marker-shell"><span class="motion-marker-icon" style="--motion-heading:${angle}deg"><i data-lucide="${motionIcon(row)}"></i></span><span class="motion-marker-speed">${kmh==null?'—':kmh.toFixed(kmh<10?1:0)} <small>km/h</small></span><span class="motion-marker-name">${esc(name)}</span></div>`;}
function effectiveSpeed(coords,now){const native=Number(coords.speed);let speed=Number.isFinite(native)&&native>=0?native:null;if(speed==null&&lastMotionPoint){const dt=(now-lastMotionPoint.at)/1000;if(dt>=2){const km=distanceKm({latitude:lastMotionPoint.latitude,longitude:lastMotionPoint.longitude},{latitude:coords.latitude,longitude:coords.longitude});speed=km*1000/dt;}}lastMotionPoint={latitude:coords.latitude,longitude:coords.longitude,at:now};return Number.isFinite(speed)&&speed>=0&&speed<80?speed:null;}
function classifyMotion(speedMs){const kmh=Math.max(0,Number(speedMs)||0);motionSamples.push(kmh);if(motionSamples.length>5)motionSamples.shift();const sorted=[...motionSamples].sort((a,b)=>a-b),median=sorted[Math.floor(sorted.length/2)]*3.6;if(median<1.5)return'still';if(median<10)return'walking';return'vehicle';}
function renderLocations(fit=false){if(view!=='mapa'||!mapInstance)return;renderMapMeta();const names=state.settings.data.names,people=document.querySelector('#location-people'),mine=locationRows.find(r=>String(r.person)===String(state.person));if(people)people.innerHTML=names.map((name,i)=>{const row=locationRows.find(r=>String(r.person)===String(i)),valid=row&&row.sharing&&Number.isFinite(Number(row.latitude));const kmh=speedKmh(row),motion=motionLabel(row);return `<article class="location-person"><span class="location-avatar">${esc(name[0])}</span><div><b>${esc(name)}</b><small><strong>${esc(row?.status||locationStatus(row))}</strong>${valid?' · '+esc(relativeLocationTime(row.updated_at))+(row.accuracy!=null?' · ±'+Math.round(row.accuracy)+' m':''):''}</small>${valid?`<small class="location-motion"><b>${esc(motion)}</b>${kmh!=null?' · '+kmh.toFixed(kmh<10?1:0)+' km/h':''}</small>`:''}</div><button class="btn text-button" data-action="location-focus" data-person="${i}" ${valid?'':'disabled'}>Centrar</button></article>`;}).join('');const controls=document.querySelector('#location-controls');if(controls)controls.innerHTML=locationWatch!==null||mine?.sharing?btn('Dejar de compartir','location-stop','secondary'):btn(icon('pin')+' Compartir mi ubicación','location-start','primary');const bounds=[];for(const row of locationRows){const id=String(row.person);if(!row.sharing){mapMarkers[id]?.remove();mapAccuracy[id]?.remove();delete mapMarkers[id];delete mapAccuracy[id];continue;}const lat=Number(row.latitude),lng=Number(row.longitude);if(!Number.isFinite(lat)||!Number.isFinite(lng))continue;const name=names[Number(id)]||'Nosotros',pos=[lat,lng];bounds.push(pos);const markerIcon=L.divIcon({className:'couple-map-marker motion-person-'+id+' motion-'+(row.motion||'unknown'),html:motionMarkerHtml(row,name),iconSize:[86,78],iconAnchor:[43,39]});if(!mapMarkers[id])mapMarkers[id]=L.marker(pos,{icon:markerIcon}).addTo(mapInstance).bindTooltip(esc(name));else mapMarkers[id].setLatLng(pos).setIcon(markerIcon);if(!mapAccuracy[id])mapAccuracy[id]=L.circle(pos,{radius:Number(row.accuracy)||0,className:'location-accuracy'}).addTo(mapInstance);else mapAccuracy[id].setLatLng(pos).setRadius(Number(row.accuracy)||0);}for(const m of Object.values(mapPlaceMarkers))m.remove();mapPlaceMarkers={};for(const p of mapPlaces){mapPlaceMarkers[p.id]=L.marker([p.latitude,p.longitude],{icon:L.divIcon({className:'map-place-marker kind-'+p.kind,html:'<span><i data-lucide="'+({home:'house',work:'briefcase-business',memory:'heart',adventure:'sparkles'}[p.kind]||'map-pin')+'"></i></span>',iconSize:[34,34],iconAnchor:[17,17]})}).addTo(mapInstance).bindTooltip(esc(p.name));}for(const l of Object.values(mapTripLines))l.remove();mapTripLines={};for(const person of ['0','1']){const pts=mapTripPoints.filter(x=>String(x.person)===person).map(x=>[x.latitude,x.longitude]);if(pts.length>1)mapTripLines[person]=L.polyline(pts,{className:'trip-line person-'+person}).addTo(mapInstance);}if(fit&&bounds.length)mapInstance.fitBounds(bounds,{padding:[45,45],maxZoom:17});refreshIcons();}
async function initMap(){if(view!=='mapa')return;if(!window.L){document.querySelector('#couple-map').innerHTML='<div class="map-loading">No pudimos cargar el mapa.</div>';return;}mapInstance=L.map('couple-map',{zoomControl:true}).setView([4.65,-74.08],12);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(mapInstance);mapMarkers={};mapAccuracy={};await loadLocations(true);const mine=locationRows.find(r=>String(r.person)===String(state.person));if(mine?.sharing&&locationWatch===null)startLocationSharing(false);locationUnsubscribe?.();locationUnsubscribe=globalThis.__galaxySubscribeLocations?.(()=>loadLocations(false).catch(()=>{}))||null;clearInterval(locationPoll);locationPoll=setInterval(()=>loadLocations(false).catch(()=>{}),15000);}
async function startLocationSharing(announce=true){if(!navigator.geolocation)throw Error('Este dispositivo no ofrece ubicación GPS al navegador.');if(locationWatch!==null)return;locationWatch=navigator.geolocation.watchPosition(async pos=>{const now=Date.now();if(now-lastLocationSent<4000)return;lastLocationSent=now;const x=pos.coords,mine=locationRows.find(r=>String(r.person)===String(state.person)),speed=effectiveSpeed(x,now),motion=classifyMotion(speed);try{await api('/api/location',{method:'PUT',body:JSON.stringify({sharing:true,latitude:x.latitude,longitude:x.longitude,accuracy:x.accuracy,speed,heading:x.heading,motion})});await detectSmartPlace(x.latitude,x.longitude);if(now-lastHistorySent>(motion==='still'?60000:15000)){lastHistorySent=now;await api('/api/map/history/point',{method:'POST',body:JSON.stringify({latitude:x.latitude,longitude:x.longitude,accuracy:x.accuracy,speed,heading:x.heading,motion})});}if(mine?.trip_active&&now-lastTripSent>15000){lastTripSent=now;await api('/api/map/trip/point',{method:'POST',body:JSON.stringify({latitude:x.latitude,longitude:x.longitude})});}if(view==='mapa')await loadLocations(false);}catch(e){toast(e.message);}},error=>{if(locationWatch!==null){navigator.geolocation.clearWatch(locationWatch);locationWatch=null;}toast(({1:'No se concedió permiso para compartir tu ubicación.',2:'El teléfono no pudo determinar tu ubicación.',3:'El GPS tardó demasiado.'})[error.code]||'No pudimos obtener tu ubicación.');},{enableHighAccuracy:true,maximumAge:5000,timeout:15000});if(announce)toast('Cuando aceptes el permiso, aparecerás en el mapa.');}
async function stopLocationSharing(){motionSamples=[];lastMotionPoint=null;lastHistorySent=0;if(locationWatch!==null){navigator.geolocation.clearWatch(locationWatch);locationWatch=null;}await api('/api/location',{method:'PUT',body:JSON.stringify({sharing:false})});await loadLocations(false);toast('Dejaste de compartir tu ubicación.');}
function focusLocation(person){const row=locationRows.find(r=>String(r.person)===String(person));if(row?.sharing)mapInstance.setView([Number(row.latitude),Number(row.longitude)],17);}
async function currentPoint(){let mine=locationRows.find(r=>String(r.person)===String(state.person));if(!mine?.sharing){await startLocationSharing(true);throw Error('Activa tu ubicación y vuelve a tocar cuando aparezcas en el mapa.');}return mine;}
async function savePlace(kind,name,note=''){const p=await currentPoint();await api('/api/map/place',{method:'POST',body:JSON.stringify({kind,name,latitude:p.latitude,longitude:p.longitude,note})});await loadLocations(false);toast(name+' quedó guardado en su mapa.');}
function settings(){const d=state.settings.data;return `${heading('HECHO A NUESTRA MEDIDA','Nuestro espacio.','Los nombres, las fechas y las conexiones que hacen de este lugar algo suyo.')}<div class="theme-panel card"><div><span class="eyebrow">APARIENCIA</span><h2>¿Cómo se siente nuestra galaxia hoy?</h2><p class="muted">Déjala cambiar con la temporada o elijan un universo cuando quieran.</p></div><div class="theme-choices">${themeOptions().map(([id,label])=>`<button type="button" class="theme-choice ${document.documentElement.dataset.themeChoice===id?'selected':''}" data-action="theme" data-value="${id}"><i class="theme-swatch swatch-${id}"></i><span>${label}</span></button>`).join('')}</div></div><div class="settings-grid"><section class="card"><span class="eyebrow">NOSOTROS DOS</span><h2>Lo que nos hace nosotros</h2><form id="settings-form"><div class="form-row"><label>Tu nombre<input name="name0" required maxlength="40" value="${esc(d.names[0])}"></label><label>Su nombre<input name="name1" required maxlength="40" value="${esc(d.names[1])}"></label></div><label>El día en que empezó nuestra historia<input type="date" name="startDate" max="${state.today}" value="${esc(d.startDate)}"></label><p class="fine-print">Pueden dejarlo vacío y completarlo cuando quieran.</p><label>Enlace de nuestro álbum de Google Fotos<input type="url" name="albumUrl" placeholder="https://photos.app.goo.gl/…" value="${esc(d.albumUrl)}"></label><button class="btn primary">Guardar nuestro espacio</button><p class="inline-error" role="alert"></p></form></section><section class="card"><span class="eyebrow">FOTOS QUE SIGUEN CON NOSOTROS</span><h2>Nuestras conexiones</h2><div class="connection-row"><span class="connection-icon">${icon('photo')}</span><div><b>Google Fotos</b><p>${state.connections.photos?'Cuenta conectada · selecciona qué importar':'Elijan las fotos que quieren traer a la aplicación.'}</p></div></div>${state.connections.photos?btn('Elegir fotos','picker','secondary'):`<a class="btn secondary" ${state.demo?'data-action="google-info" href="#ajustes"':'href="/auth/google?feature=photos"'}>Conectar Google Fotos ${icon('arrow')}</a>`}<p class="fine-print">El enlace compartido abre su álbum en Google Fotos. Para verlo aquí, importen una selección. No se sincroniza automáticamente.</p><hr><div class="connection-row"><span class="connection-icon">${icon('cloud')}</span><div><b>Google Drive</b><p>${state.connections.drive?'Cuenta conectada':'Opcional: ver fotos de una carpeta compartida.'}</p></div></div>${state.connections.drive?`<form id="drive-form"><label>Carpeta compartida<input name="url" required placeholder="https://drive.google.com/drive/folders/…" value="${d.folderId?'https://drive.google.com/drive/folders/'+esc(d.folderId):''}"></label><button class="btn secondary">Conectar carpeta</button><p class="inline-error" role="alert"></p></form>`:`<a class="btn secondary" ${state.demo?'data-action="google-info" href="#ajustes"':'href="/auth/google?feature=drive"'}>Conectar Google Drive ${icon('arrow')}</a>`}<p class="fine-print">Drive solicita permiso de lectura; la aplicación muestra solo la carpeta que elijan. Ambos necesitan acceso a esa carpeta.</p>${!state.demo?btn('Desconectar permisos de Google','disconnect','text-button'):''}</section><section class="card"><span class="eyebrow">SU HISTORIA LES PERTENECE</span><h2>Guardar y salir</h2><p class="muted">Descarga sus recuerdos, planes, canciones, fechas y notas en un archivo. Las fotos se conservan aparte en el servidor.</p><a class="btn secondary" href="/api/export">Descargar nuestros datos ${icon('arrow')}</a>${!state.demo?btn('Cerrar sesión','logout','text-button'):''}<p class="fine-print">${state.demo?'Vista local: los cambios se guardan en este computador. Para compartir entre sus celulares hace falta activar Google y alojar la aplicación.':'Espacio privado: solo las dos cuentas configuradas pueden entrar.'}</p></section><section class="card gift-settings"><img src="/icon.svg" alt="" width="60" height="60"><h2>Siempre habrá girasoles.</h2><p>La carta, las seis flores y el pequeño secreto que dieron comienzo a este universo.</p><a href="/regalo/" class="btn secondary">Abrir el regalo original ${icon('arrow')}</a></section></div>`;}
const kindLabels={memory:['recuerdo','Guardar recuerdo'],song:['canción','Guardar canción'],event:['fecha','Guardar fecha'],plan:['plan','Guardar plan'],note:['nota','Guardar nota']};
function editor(kind,item=null,defaults={}){const d=item?.data||{title:'',body:'',date:'',category:'',url:'',audioUrl:'',audioPath:'',...defaults};const [label,submit]=kindLabels[kind];show(`<span class="eyebrow">UN PEDACITO MÁS DE NOSOTROS</span><h2 id="modal-title">${item?'Editar':'Añadir'} ${label}</h2><form id="item-form" data-kind="${kind}" ${item?`data-id="${item.id}" data-version="${item.version}"`:''}><label>${kind==='song'?'Nombre de la canción':'Título'}<input name="title" required maxlength="120" value="${esc(d.title)}" placeholder="Dale un nombre a este momento"></label>${kind==='song'?`<label>Enlace de Spotify, YouTube o audio directo (opcional)<input name="url" type="url" value="${esc(d.url||'')}" placeholder="https://…"></label><input name="audioUrl" type="hidden" value="${esc(d.audioUrl||'')}"><input name="audioPath" type="hidden" value="${esc(d.audioPath||'')}"><div class="song-upload-box"><p>O súbela directamente en MP3 para reproducirla dentro de la app.</p>${btn(icon('cloud')+' Elegir MP3','choose-song-file','secondary')}<span id="song-file-name" class="muted">${d.audioUrl?'MP3 ya cargado':''}</span></div>`:''}<label>${kind==='song'?'¿Por qué te recuerda a nosotros?':kind==='note'?'Lo que quieres decirle':'Cuéntanos un poquito más'}<textarea name="body" maxlength="5000" rows="4" placeholder="Las pequeñas cosas también merecen guardarse…">${esc(d.body)}</textarea></label>${['event','plan','memory'].includes(kind)?`<div class="form-row"><label>Fecha ${kind==='event'?'':'(opcional)'}<input name="date" type="date" ${kind==='event'?'required':''} value="${esc(d.date)}"></label><label>Categoría<input name="category" maxlength="40" value="${esc(d.category)}"></label></div>`:''}${kind==='event'?`<label class="check-label"><input type="checkbox" name="annual" ${d.annual?'checked':''}> Celebrarlo cada año</label>`:''}<p class="form-error" role="alert" tabindex="-1"></p><div class="form-actions">${item?btn(icon('trash')+' Eliminar','delete','danger',`data-id="${item.id}"`):'<span></span>'}<button class="btn primary" type="submit">${submit} ${icon('check')}</button></div></form>`);}
function detail(id){const i=state.items.find(i=>i.id===id);if(!i)return;show(`<span class="eyebrow">${esc(i.data.category||kindLabels[i.kind][0])}</span><h2 id="modal-title">${esc(i.data.title)}</h2>${i.data.date?`<p class="muted">${dateLabel(i.data.date,{year:'numeric'})}</p>`:''}<p class="detail-body">${esc(i.data.body)}</p><div class="form-actions"><span>De ${esc(state.settings.data.names[Number(i.author)]||'nosotros')}</span>${btn(icon('edit')+' Editar','edit','secondary',`data-id="${id}"`)}</div>`);}
async function mutate(url,method,data,message){await api(url,{method,body:JSON.stringify(data)});close();await refresh();toast(message);}
async function action(el,event=null){const a=el.dataset.action,id=el.dataset.id,item=state?.items.find(i=>i.id===id);if(a?.startsWith('new-')&&kindLabels[a.slice(4)])return editor(a.slice(4));switch(a){
 case'map-menu':{const menu=document.querySelector('#map-fab-menu'),other=document.querySelector('#map-status-menu'),open=menu?.hidden;if(other)other.hidden=true;if(menu)menu.hidden=!open;el.setAttribute('aria-expanded',String(open));el.classList.toggle('open',open);return refreshIcons();}
 case'status-menu':{const menu=document.querySelector('#map-status-menu'),other=document.querySelector('#map-fab-menu'),open=menu?.hidden;if(other)other.hidden=true;if(menu)menu.hidden=!open;el.setAttribute('aria-expanded',String(open));el.classList.toggle('open',open);return refreshIcons();}
 case'location-start':return startLocationSharing(true);
 case'location-status':{const mine=await currentPoint();await api('/api/location',{method:'PUT',body:JSON.stringify({sharing:true,latitude:mine.latitude,longitude:mine.longitude,accuracy:mine.accuracy,status:el.dataset.value})});await loadLocations(false);return toast('Estado compartido.');}
 case'trip-toggle':{const mine=await currentPoint();if(mine.trip_active){await api('/api/map/trip/end',{method:'POST',body:'{}'});await loadLocations(false);return toast('Acompáñame terminó y el recorrido temporal fue eliminado.');}await api('/api/location',{method:'PUT',body:JSON.stringify({sharing:true,latitude:mine.latitude,longitude:mine.longitude,accuracy:mine.accuracy,trip_active:true,status:'En camino'})});await loadLocations(false);return toast('Acompáñame está activo mientras Nuestra Galaxia siga ejecutándose.');}
 case'arrived':{const mine=await currentPoint();await api('/api/location',{method:'PUT',body:JSON.stringify({sharing:true,latitude:mine.latitude,longitude:mine.longitude,accuracy:mine.accuracy,status:'Llegué'})});return toast('Ya sabe que llegaste ♡');}
 case'lost-mode':{const mine=await currentPoint();mapInstance.setView([mine.latitude,mine.longitude],18);await api('/api/location',{method:'PUT',body:JSON.stringify({sharing:true,latitude:mine.latitude,longitude:mine.longitude,accuracy:mine.accuracy,status:'Ayúdame a llegar'})});return toast('Tu posición quedó centrada y marcada para que pueda ayudarte.');}
 case'mobility-history':return show('<h2 id="modal-title">Nuestros recorridos</h2><div class="trip-history-list">'+(tripHistory.length?tripHistory.map(t=>'<article class="trip-history-row"><div><b>'+esc(state.settings.data.names[Number(t.person)]||'Nosotros')+'</b><small>'+new Date(t.started_at).toLocaleString('es-CO')+' · '+(Number(t.distance_m)/1000).toFixed(1)+' km · '+formatDuration(t.duration_s)+'</small></div>'+(String(t.person)===String(state.person)?'<button class="btn text-button" data-action="trip-history-delete" data-id="'+t.id+'">Eliminar</button>':'')+'</article>').join(''):'<p class="muted">Todavía no hay recorridos terminados.</p>')+'</div>');
 case'trip-history-delete':await api('/api/map/trip/history/'+id,{method:'DELETE'});await loadLocations(false);close();return toast('Recorrido eliminado.');
 case'mobility-export':{const data=await api('/api/map/privacy/export'),blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='mi-historial-nuestra-galaxia.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return toast('Tu historial se exportó en JSON.');}
 case'mobility-clear':return show('<h2 id="modal-title">¿Borrar tu historial de movilidad?</h2><p>Se eliminarán tus muestras, recorridos y eventos de llegada. Los lugares Casa/Trabajo/recuerdos no se borrarán.</p><div class="button-row">'+btn('Conservarlo','close','secondary')+btn('Borrar mi historial','mobility-clear-confirm','danger')+'</div>');
 case'mobility-clear-confirm':await api('/api/map/privacy/history',{method:'DELETE'});close();await loadLocations(false);return toast('Tu historial de movilidad fue eliminado.');
 case'place-home':return savePlace('home','Casa');
 case'place-work':return savePlace('work','Trabajo');
 case'place-new':return show('<h2 id="modal-title">Guardar este lugar</h2><p>Guarda tu ubicación actual como un recuerdo o una próxima aventura.</p><form id="map-place-form"><label>Nombre<input name="name" maxlength="80" required placeholder="Nuestro lugar"></label><label>Tipo<select name="kind"><option value="memory">Recuerdo</option><option value="adventure">Próxima aventura</option></select></label><label>Nota<textarea name="note" maxlength="300"></textarea></label><button class="btn primary">Guardar lugar</button></form>');
 case'place-focus':{const p=mapPlaces.find(x=>String(x.id)===String(el.dataset.id));if(p)mapInstance.setView([p.latitude,p.longitude],17);return;}
 case'location-stop':return stopLocationSharing();
 case'location-focus':return focusLocation(el.dataset.person);
 case'theme':applyTheme(el.dataset.value);draw();return toast('La galaxia cambió de ambiente.');
 case'more':return show(`<h2 id="modal-title">Todo nuestro universo</h2><div class="more-nav">${nav.map(([id,i,label])=>`<a href="#${id}">${icon(i)}${label}${icon('arrow')}</a>`).join('')}<a href="#ajustes">${icon('settings')}Ajustes${icon('arrow')}</a><a href="/regalo/">${icon('sun')}El regalo original${icon('arrow')}</a></div>`);
 case'close':return close();case'settings':location.hash='ajustes';return;case'detail':return detail(id);case'edit':close();return editor(item.kind,item);
 case'delete':return show(`<h2 id="modal-title">¿Eliminar este ${kindLabels[item.kind][0]}?</h2><p>Se quitará de su espacio compartido. Esta acción no se puede deshacer.</p><div class="button-row">${btn('Conservarlo','close','secondary')}${btn('Sí, eliminar','confirm-delete','danger',`data-id="${id}"`)}</div>`);
 case'confirm-delete':return mutate('/api/items/'+id,'DELETE',{version:item.version},'Contenido eliminado.');
 case'mood':await api('/api/daily',{method:'POST',body:JSON.stringify({field:'mood',value:el.dataset.value})});await refresh();return toast('Gracias por compartir cómo te sientes.');
 case'filter':filter=el.dataset.value;return draw();
 case'shuffle-idea':ideaIndex=(ideaIndex+1+Math.floor(Math.random()*(state.ideas.length-1)))%state.ideas.length;return draw();
 case'save-idea':case'ritual':{const idea=state.ideas[a==='ritual'?Number(el.dataset.index):ideaIndex];return editor('plan',null,{title:idea.title,body:idea.text,category:idea.category});}
 case'complete':await api('/api/items/'+id,{method:'PUT',body:JSON.stringify({...item.data,version:item.version,done:!item.data.done})});await refresh();return toast(item.data.done?'El plan volvió a los pendientes.':'Un plan vivido. Un recuerdo más. ♡');
 case'prev-month':month--;if(month<0){month=11;year--;}return draw();case'next-month':month++;if(month>11){month=0;year++;}return draw();case'today':year=Number(state.today.slice(0,4));month=Number(state.today.slice(5,7))-1;return draw();
 case'day':{const date=el.dataset.date,list=items('event').filter(e=>e.data.annual?e.data.date.slice(5)===date.slice(5)&&e.data.date<=date:e.data.date===date);if(!list.length)return editor('event',null,{date});return show(`<h2 id="modal-title">${dateLabel(date,{year:'numeric'})}</h2>${list.map(e=>`<button class="day-event" data-action="detail" data-id="${e.id}">${esc(e.data.title)} ${icon('arrow')}</button>`).join('')}${btn('Añadir otra fecha','new-on-day','secondary',`data-date="${date}"`)}`);}
 case'new-on-day':close();return editor('event',null,{date:el.dataset.date});
 case'music-toggle':if(bgAudio.paused)await tryMusic();else bgAudio.pause();updateMiniPlayer();if(view==='musica')draw();return;
 case'choose-song-file':document.querySelector('#song-upload-picker')?.remove();{const input=document.createElement('input');input.id='song-upload-picker';input.type='file';input.accept='audio/mpeg,.mp3';input.hidden=true;document.body.append(input);input.click();return;}
 case'play-song':{if(item.data.audioUrl){setTrack(item.data.audioUrl,item.data.title,item.id);return toast('Reproduciendo en Nuestra galaxia.');}return show(`<span class="eyebrow">${esc(item.data.provider)}</span><h2 id="modal-title">${esc(item.data.title)}</h2><p>${esc(item.data.body)}</p><iframe class="player ${item.data.provider==='YouTube'?'video':''}" src="${esc(item.data.embed)}" title="Escuchar ${esc(item.data.title)}" allow="autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture" allowfullscreen></iframe><a class="text-link" href="${esc(item.data.url)}" target="_blank" rel="noopener noreferrer">Abrir en ${esc(item.data.provider)} ${icon('arrow')}</a>`,true);}
 case'upload':document.querySelector('#photo-upload').click();return;
 case'photo-source':photoSource=el.dataset.value;return draw();case'reload-photos':return loadPhotos();
 case'drive-more':{const batch=await api('/api/drive/photos?page='+encodeURIComponent(drivePage));drivePhotos.push(...batch.files);drivePage=batch.nextPageToken||'';return renderPhotos();}
 case'photo':{const p=(photoSource==='drive'?drivePhotos:photos).find(p=>p.id===id);return show(`<h2 id="modal-title">${esc(p.name)}</h2><img class="lightbox-photo" src="${photoSource==='drive'?'/api/drive/image/':'/media/'}${encodeURIComponent(id)}" alt="${esc(p.name)}">${photoSource==='local'?btn('Quitar del álbum','delete-photo','text-button',`data-id="${id}"`):''}`,true);}
 case'delete-photo':return show(`<h2 id="modal-title">¿Quitar esta foto?</h2><p>Se elimina la copia de esta aplicación. El original de Google Fotos o del celular no cambia.</p><div class="button-row">${btn('Conservarla','close','secondary')}${btn('Quitar foto','confirm-delete-photo','danger',`data-id="${id}"`)}</div>`);
 case'confirm-delete-photo':return mutate('/api/photos/'+id,'DELETE',{},'Foto eliminada del álbum.');
 case'google-info':return show(`<span class="eyebrow">ESTAMOS EN LA VISTA LOCAL</span><h2 id="modal-title">Conectar su cuenta de Google</h2><p>La aplicación ya incluye la conexión. Para activarla necesita sus credenciales de Google y las dos cuentas autorizadas en el servidor.</p><p>Mientras tanto, pueden subir fotos, añadir canciones y completar su historia. Todo se guarda en este computador.</p>${btn('Entendido','close','primary')}`);
 case'picker':if(!state.connections.photos){if(state.demo)return action({dataset:{action:'google-info'}});location.href='/auth/google?feature=photos';return;}const p=await api('/api/picker',{method:'POST',body:'{}'});pickerId=p.id;sessionStorage.setItem('pickerId',p.id);show(`<h2 id="modal-title">Elijan sus fotos favoritas</h2><p>Se abrirá el selector de Google Fotos. Elijan hasta 30 fotos y regresen para importarlas a su álbum privado.</p><a class="btn primary" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Elegir en Google Fotos ${icon('arrow')}</a><p>Cuando terminen:</p>${btn('Importar selección','picker-import','secondary')}`);return;
 case'picker-import':{toast('Importando la selección…');const r=await api('/api/picker/import',{method:'POST',body:JSON.stringify({id:pickerId})});if(r.pending)return toast('Termina de seleccionar las fotos en Google y vuelve a intentar.');pickerId='';sessionStorage.removeItem('pickerId');close();location.hash='album';await refresh();return toast(`${r.imported} fotos importadas.${r.skipped?' Los videos no se importaron.':''}`);}
 case'disconnect':return show(`<h2 id="modal-title">¿Desconectar Google?</h2><p>Se revocarán los permisos de fotos y Drive de tu cuenta. Las fotos que ya importaste seguirán en su álbum; puedes eliminarlas allí.</p>${btn('Desconectar','confirm-disconnect','danger')}`);
 case'confirm-disconnect':await api('/api/google/disconnect',{method:'POST',body:'{}'});close();await refresh();return toast('Google desconectado.');
 case'logout':await api('/api/logout',{method:'POST',body:'{}'});location.reload();return;
 }}
document.addEventListener('pointerdown',unlockMusic,{once:true});
bgAudio.addEventListener('play',updateMiniPlayer);bgAudio.addEventListener('pause',updateMiniPlayer);
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el)return;event.preventDefault();if(el.disabled)return;el.disabled=true;try{await action(el,event);}catch(e){if(modal.open)formError(e.message);else toast(e.message);}finally{el.disabled=false;}});
document.addEventListener('submit',async event=>{const f=event.target;event.preventDefault();const data=Object.fromEntries(new FormData(f));const submit=f.querySelector('[type="submit"],button:not([type])');if(submit)submit.disabled=true;try{
 if(f.id==='map-place-form'){await savePlace(data.kind,data.name,data.note);close();}
 if(f.id==='item-form'){const item=state.items.find(i=>i.id===f.dataset.id);const payload={...item?.data,...data,kind:f.dataset.kind,annual:!!data.annual,version:Number(f.dataset.version)};await mutate('/api/items'+(item?'/'+item.id:''),item?'PUT':'POST',payload,'Guardado en su universo. ♡');}
 if(f.id==='settings-form'){await api('/api/settings',{method:'PUT',body:JSON.stringify({names:[data.name0,data.name1],startDate:data.startDate,albumUrl:data.albumUrl,version:state.settings.version})});await refresh();toast('Su espacio, a su manera.');}
 if(f.id==='answer-form'){await api('/api/daily',{method:'POST',body:JSON.stringify({field:'answer',value:data.answer})});await refresh();toast(state.allAnswered?'Sus dos respuestas ya están abiertas. ♡':'Tu respuesta quedó guardada.');}
 if(f.id==='drive-form'){await api('/api/drive/folder',{method:'POST',body:JSON.stringify(data)});await refresh();toast('Carpeta conectada.');}
 }catch(e){const error=f.querySelector('.inline-error,.form-error');if(error)error.textContent=e.message;else toast(e.message);}finally{if(submit)submit.disabled=false;}});
document.addEventListener('change',async event=>{try{
 if(event.target.id==='song-upload-picker'){const file=event.target.files?.[0];if(!file)return;if(file.type!=='audio/mpeg'&&!file.name.toLowerCase().endsWith('.mp3'))throw Error('Selecciona un archivo MP3.');if(file.size>20971520)throw Error('El MP3 puede pesar máximo 20 MB.');toast('Subiendo canción…');const result=await api('/api/music/upload',{method:'POST',body:file,headers:{'Content-Type':'application/octet-stream','X-File-Name':encodeURIComponent(file.name)}});const field=modal.querySelector('input[name="audioUrl"]');if(field)field.value=result.url;const pathField=modal.querySelector('input[name="audioPath"]');if(pathField)pathField.value=result.path;const label=modal.querySelector('#song-file-name');if(label)label.textContent=file.name;event.target.remove();toast('MP3 listo para guardar.');}
if(event.target.id==='demo-person'){await api('/api/demo-person',{method:'POST',body:JSON.stringify({person:event.target.value})});await refresh();}
 if(event.target.id==='photo-upload'){const files=[...event.target.files];if(files.length>30)throw Error('Selecciona hasta 30 fotos por vez.');let count=0;for(const file of files){toast(`Subiendo foto ${count+1} de ${files.length}…`);await api('/api/photos/upload',{method:'POST',body:file,headers:{'Content-Type':'application/octet-stream','X-File-Name':encodeURIComponent(file.name)}});count++;}await refresh();toast(`${count} fotos guardadas en su álbum.`);}
 }catch(e){toast(e.message);if(view==='album')loadPhotos();}});
document.addEventListener('input',event=>{if(event.target.id==='memory-search'){search=event.target.value;const caret=event.target.selectionStart;document.querySelector('#main').innerHTML=memories();const input=document.querySelector('#memory-search');input.focus();input.setSelectionRange(caret,caret);}});
modal.addEventListener('close',()=>{modal.querySelectorAll('iframe').forEach(f=>f.remove());});
window.addEventListener('hashchange',()=>{if(modal.open)close();clearInterval(locationPoll);locationPoll=null;if(locationUnsubscribe){locationUnsubscribe();locationUnsubscribe=null;}if(mapInstance){mapInstance.remove();mapInstance=null;}view=location.hash.slice(1)||'inicio';filter='Todos';draw();window.scrollTo(0,0);});
async function boot(){try{await refresh();if(new URLSearchParams(location.search).has('auth')){toast('La conexión se canceló. Puedes intentarlo de nuevo en Ajustes.');history.replaceState(null,'',location.pathname);}}catch(e){app.innerHTML=`<section class="login"><img src="/icon.svg" width="64" height="64" alt=""><p class="eyebrow">UN ESPACIO PARA DOS</p><h1>El mundo es grande.<br><em>Lo nuestro es aquí.</em></h1><p>Fotos, canciones, planes y todos esos pequeños<br>momentos que hacen una vida juntos.</p><a href="/auth/google" class="btn primary">Entrar con Google ${icon('arrow')}</a><small>${icon('lock')} Solo las dos cuentas invitadas pueden entrar.</small><p class="fine-print">${esc(e.message)}</p></section>`;}}
// Refresca al regresar a la pestaña sin interrumpir una respuesta o un formulario abierto.
function safeToRefresh(){return !document.hidden&&state&&!modal.open&&!document.querySelector('form')&&!document.querySelector('input:focus')&&![...document.querySelectorAll('audio')].some(a=>!a.paused)&&view!=='album';}
async function sync(){
 if(document.hidden||!state||modal.open)return;
 if(view==='conectar'){
  const next=await api('/api/state');if(view!=='conectar'||modal.open)return;
  // Actualiza las respuestas de la pareja sin borrar el borrador que se está escribiendo.
  if(next.today!==state.today)return;
  state=next;const grid=document.querySelector('.answer-grid');
  if(grid)grid.innerHTML=state.settings.data.names.map((n,i)=>{const d=state.daily.find(d=>d.person===String(i));return `<article><span class="answer-avatar">${esc(n[0])}</span><b>${esc(n)}</b><p>${d?.answer?esc(d.answer):d?.answered?'Su respuesta está guardada. Se abrirá cuando ambos respondan.':'Todavía está pensando su respuesta.'}</p></article>`;}).join('');return;
 }
 if(!safeToRefresh())return;
 const currentView=view,next=await api('/api/state');if(view!==currentView||!safeToRefresh())return;
 if(JSON.stringify(next)!==JSON.stringify(state)){state=next;draw();}
}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)sync().catch(()=>toast('No hay conexión. Tus cambios guardados siguen a salvo.'));});
setInterval(()=>sync().catch(()=>{}),30000);
setupPwa(html=>{app.innerHTML=html;}).then(async blocked=>{if(!blocked){await boot();tryMusic();}});
